#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Consolidating SuccessModal / SucessModal into one file..."

echo "  components/SuccessModal.js"
mkdir -p "$(dirname 'components/SuccessModal.js')"
echo '' | base64 --decode > 'components/SuccessModal.js'

echo "  screens/ManageCaregiverScreen.js"
mkdir -p "$(dirname 'screens/ManageCaregiverScreen.js')"
echo '' | base64 --decode > 'screens/ManageCaregiverScreen.js'

echo "  screens/NotificationSettingsScreen.js"
mkdir -p "$(dirname 'screens/NotificationSettingsScreen.js')"
echo '' | base64 --decode > 'screens/NotificationSettingsScreen.js'

echo "  screens/EditDetailsScreen.js"
mkdir -p "$(dirname 'screens/EditDetailsScreen.js')"
echo '' | base64 --decode > 'screens/EditDetailsScreen.js'

if [ -f components/SucessModal.js ]; then
  echo "  removing components/SucessModal.js (duplicate)"
  rm components/SucessModal.js
fi

echo "Done."
